+}
+.hero-tile {
+  border-radius: var(--radius);
+  position: relative;
+  overflow: hidden;
+}
+.tile-1 {
+  background:
+    radial-gradient(circle at 30% 30%, #e8d6c2 0%, #c9a989 60%, #a87d5b 100%);
