  gap: 22px 18px;
}
@media (max-width: 980px) { .product-grid { grid-template-columns: repeat(3, 1fr); } }
@media (max-width: 720px) { .product-grid { grid-template-columns: repeat(2, 1fr); } }

.product {
  background: transparent;
  display: flex;
  flex-direction: column;
  position: relative;
}
.product-media {
  position: relative;
  aspect-ratio: 4 / 5;
  border-radius: var(--radius);
  overflow: hidden;
  background: var(--sand);
}
.product-media::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 65% 75%, rgba(255,255,255,0.18), transparent 55%),
