  background: #232220;
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
}
.deal-feature { grid-row: span 1; }
.deal-art {
  aspect-ratio: 16 / 9;
  position: relative;
}
.deal-feature .deal-art { aspect-ratio: 16 / 8; }
.deal-art-1 { background: linear-gradient(135deg, #c9b496 0%, #8e6a48 100%); }
.deal-art-2 { background: linear-gradient(135deg, #6b7a5a 0%, #3e4734 100%); }
.deal-art-3 { background: linear-gradient(135deg, #5a4754 0%, #2f2530 100%); }
.deal-body { padding: 22px; display: flex; flex-direction: column; gap: 4px; }
.deal-body h3 { color: #fff; font-size: 1.4rem; }
.deal-feature .deal-body h3 { font-size: 1.7rem; }
.deal-body p { color: #c8c2b8; }
.deal-body .btn { align-self: flex-start; margin-top: 8px; background: #fff; color: var(--ink); border-color: #fff; }
