/* ---------- Newsletter ---------- */
.newsletter {
  background: var(--sand);
  max-width: none;
  margin: 0;
}
.newsletter-inner {
  max-width: var(--maxw);
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 1.1fr;
  gap: clamp(24px, 5vw, 56px);
  align-items: center;
