', direction=None, fact=None, file_name='/workspace/sandbox/variants/accessible_basic/shopping-home-page--framework-vanilla-js--style-modern/claude-opus-4.7__s4/styles.css', full_command_text=None, has_write_file_redirection=None, hook_message=None, intention='Edit file', new_file_contents=':root {
  --bg: #faf8f5;
  --surface: #ffffff;
  --ink: #1a1a1a;
  --ink-2: #3d3a36;
  --muted: #6b6661;
  --line: #e6e1da;
  --line-strong: #c9c2b8;
  --accent: #b54a2b;
  --accent-ink: #7a3119;
  --sand: #ece5da;
  --clay: #d9c7b3;
  --moss: #6b7a5a;
  --sky: #c7d3d8;
  --plum: #5a4754;
  --focus: #1a1a1a;
  --radius: 14px;
  --radius-sm: 8px;
  --shadow-sm: 0 1px 2px rgba(20, 18, 14, 0.06);
  --shadow-md: 0 6px 24px rgba(20, 18, 14, 0.08);
  --maxw: 1200px;
  --gutter: clamp(16px, 4vw, 40px);
  --font-sans: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
    "Helvetica Neue", Arial, sans-serif;
  --font-display: "Fraunces", "Cormorant Garamond", Georgia, "Times New Roman",
    serif;
}

* { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

img, svg { display: block; max-width: 100%; }

a { color: inherit; }

p { margin: 0 0 0.75em; }

h1, h2, h3 {
  font-family: var(--font-display);
  font-weight: 500;
  letter-spacing: -0.01em;
  color: var(--ink);
  margin: 0 0 0.4em;
  line-height: 1.15;
}

h1 { font-size: clamp(2.4rem, 5.6vw, 4.2rem); }
h2 { font-size: clamp(1.6rem, 2.6vw, 2.2rem); }
h3 { font-size: 1.2rem; line-height: 1.3; }

/* Focus */
:focus { outline: none; }
:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 3px;
  border-radius: 4px;
}

.skip-link {
  position: absolute;
  left: 12px;
  top: -100px;
  background: var(--ink);
  color: #fff;
  padding: 10px 14px;
  border-radius: 6px;
  z-index: 100;
  text-decoration: none;
  font-weight: 600;
}
.skip-link:focus { top: 12px; }

/* ---------- Header ---------- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(250, 248, 245, 0.92);
  backdrop-filter: saturate(140%) blur(10px);
  border-bottom: 1px solid var(--line);
}
.header-inner {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 14px var(--gutter);
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 24px;
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  color: var(--ink);
}
.brand-mark {
  width: 32px;
  height: 32px;
  display: inline-grid;
  place-items: center;
  background: var(--ink);
  color: #fff;
  border-radius: 8px;
  font-family: var(--font-display);
  font-weight: 600;
  font-size: 14px;
}
.brand-name {
  font-family: var(--font-display);
  font-weight: 600;
  font-size: 1.15rem;
  letter-spacing: -0.01em;
}

.primary-nav ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  gap: 4px;
  justify-content: center;
}
.primary-nav a {
  display: inline-block;
  padding: 8px 14px;
  text-decoration: none;
  font-size: 0.95rem;
  color: var(--ink-2);
  border-radius: 999px;
}
.primary-nav a:hover { background: var(--sand); color: var(--ink); }

.header-actions {
  display: flex;
  gap: 4px;
  justify-content: flex-end;
  align-items: center;
}
.icon-btn {
  appearance: none;
  background: transparent;
  border: 1px solid transparent;
  width: 40px;
  height: 40px;
  display: inline-grid;
  place-items: center;
  border-radius: 999px;
  color: var(--ink);
  cursor: pointer;
  position: relative;
}
.icon-btn:hover { background: var(--sand); }
.cart-count {
  position: absolute;
  top: 4px;
  right: 4px;
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  border-radius: 999px;
  background: var(--accent);
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  display: inline-grid;
  place-items: center;
  line-height: 1;
}
.cart-count.is-zero { display: none; }

@media (max-width: 720px) {
  .primary-nav { display: none; }
  .header-inner { grid-template-columns: auto 1fr; }
}

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 20px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 0.95rem;
  text-decoration: none;
  border: 1px solid transparent;
  cursor: pointer;
  transition: transform 0.05s ease, background 0.15s ease, color 0.15s ease,
    border-color 0.15s ease;
  line-height: 1;
}
.btn:active { transform: translateY(1px); }
.btn-primary {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}
.btn-primary:hover { background: var(--accent-ink); border-color: var(--accent-ink); }
.btn-dark {
  background: var(--ink);
  color: #fff;
  border-color: var(--ink);
}
.btn-dark:hover { background: #000; }
.btn-ghost {
  background: transparent;
  color: var(--ink);
  border-color: var(--line-strong);
}
.btn-ghost:hover { background: var(--sand); border-color: var(--ink); }

.link-arrow {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  text-decoration: none;
  color: var(--ink);
  font-weight: 600;
  font-size: 0.95rem;
  border-bottom: 1px solid transparent;
  padding-bottom: 2px;
}
.link-arrow:hover { border-bottom-color: var(--ink); }

/* ---------- Section heads ---------- */
section { padding: clamp(48px, 7vw, 88px) var(--gutter); max-width: var(--maxw); margin: 0 auto; }
.section-head {
  display: flex;
  flex-wrap: wrap;
  align-items: end;
  justify-content: space-between;
  gap: 12px 24px;
  margin-bottom: 28px;
}
.section-head h2 { margin-bottom: 0; }
.section-sub { color: var(--muted); margin: 4px 0 0; font-size: 0.98rem; }
.eyebrow, .kicker {
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--accent-ink);
  margin: 0 0 14px;
}
.kicker { color: var(--muted); margin-bottom: 8px; }

/* ---------- Hero ---------- */
.hero {
  display: grid;
  grid-template-columns: 1.05fr 1fr;
  gap: clamp(24px, 5vw, 64px);
  align-items: center;
  padding-top: clamp(40px, 6vw, 72px);
}
.hero-text { max-width: 560px; }
.hero-lede {
  font-size: 1.1rem;
  color: var(--ink-2);
  max-width: 48ch;
  margin-bottom: 28px;
}
.hero-cta { display: flex; gap: 12px; flex-wrap: wrap; }

.hero-art {
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-template-rows: 180px 180px;
  gap: 14px;
  min-width: 0;
}
.hero-tile {
  border-radius: var(--radius);
  position: relative;
  overflow: hidden;
}
.tile-1 {
  background:
    radial-gradient(circle at 30% 30%, #e8d6c2 0%, #c9a989 60%, #a87d5b 100%);
  grid-row: span 2;
}
.tile-2 { background: linear-gradient(140deg, #d9d2c5, #b6b09e); }
.tile-3 { background: linear-gradient(140deg, var(--moss), #4f5b41); }
.tile-4 { background: linear-gradient(140deg, var(--sky), #8aa1a8); }

.hero-tile::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 70% 80%, rgba(255,255,255,0.18), transparent 50%),
    radial-gradient(circle at 20% 20%, rgba(255,255,255,0.12), transparent 40%);
}

@media (max-width: 820px) {
  .hero { grid-template-columns: 1fr; }
  .hero-art { grid-template-rows: 140px 140px; }
}

/* ---------- Categories ---------- */
.cat-grid {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
}
.cat-card {
  position: relative;
  display: block;
  aspect-ratio: 4 / 5;
  border-radius: var(--radius);
  overflow: hidden;
  text-decoration: none;
  color: #fff;
  font-family: var(--font-display);
  font-size: 1.4rem;
  transition: transform 0.2s ease;
}
.cat-card span {
  position: absolute;
  left: 16px;
  bottom: 14px;
  z-index: 2;
  text-shadow: 0 1px 6px rgba(0,0,0,0.4);
}
.cat-card::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,0.55) 0%, transparent 55%);
}
.cat-card:hover { transform: translateY(-2px); }

.cat-apparel { background: linear-gradient(160deg, #b9a48a, #6e5a44); }
.cat-home    { background: linear-gradient(160deg, #d8c8b6, #8a7560); }
.cat-kitchen { background: linear-gradient(160deg, #8a9b88, #4d5e4f); }
.cat-accents { background: linear-gradient(160deg, #c2a9a1, #76544d); }

@media (max-width: 720px) {
  .cat-grid { grid-template-columns: repeat(2, 1fr); }
}

/* ---------- Products ---------- */
.product-grid {
  list-style: none;
  padding: 0;
  margin: 0;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 22px 18px;
}
@media (max-width: 980px) { .product-grid { grid-template-columns: repeat(3, 1fr); } }
@media (max-width: 720px) { .product-grid { grid-template-columns: repeat(2, 1fr); } }

.product {
  background: transparent;
  display: flex;
  flex-direction: column;
  position: relative;
}
.product-media {
  position: relative;
  aspect-ratio: 4 / 5;
  border-radius: var(--radius);
  overflow: hidden;
  background: var(--sand);
}
.product-media::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 65% 75%, rgba(255,255,255,0.18), transparent 55%),
    radial-gradient(circle at 25% 25%, rgba(255,255,255,0.12), transparent 50%);
  pointer-events: none;
}
.product-tag {
  position: absolute;
  top: 10px;
  left: 10px;
  background: #fff;
  color: var(--ink);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  padding: 5px 9px;
  border-radius: 999px;
  z-index: 2;
}
.product-tag.sale { background: var(--accent); color: #fff; }
.add-btn {
  position: absolute;
  right: 10px;
  bottom: 10px;
  z-index: 2;
  appearance: none;
  background: #fff;
  color: var(--ink);
  border: 1px solid var(--line-strong);
  border-radius: 999px;
  font-weight: 600;
  font-size: 0.85rem;
  padding: 8px 14px;
  cursor: pointer;
  opacity: 0;
  transform: translateY(6px);
  transition: opacity 0.18s ease, transform 0.18s ease, background 0.15s ease,
