}
.story-body h3 a:hover { background-size: 100% 1px; }
.meta { color: var(--muted); font-size: 0.83rem; text-transform: uppercase; letter-spacing: 0.08em; margin: 8px 0 0; }

@media (max-width: 900px) {
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .story-lead { grid-column: span 2; }
}
@media (max-width: 600px) {
  .editorial-grid { grid-template-columns: 1fr; }
  .story-lead { grid-column: span 1; }
}

/* ---------- Newsletter ---------- */
.newsletter {
  background: var(--sand);
  max-width: none;
  margin: 0;
}
.newsletter-inner {
  max-width: var(--maxw);
