@media (max-width: 720px) {
  .primary-nav { display: none; }
  .header-inner { grid-template-columns: auto 1fr; }
}

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 20px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 0.95rem;
  text-decoration: none;
  border: 1px solid transparent;
  cursor: pointer;
  transition: transform 0.05s ease, background 0.15s ease, color 0.15s ease,
    border-color 0.15s ease;
  line-height: 1;
}
.btn:active { transform: translateY(1px); }
.btn-primary {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}
.btn-primary:hover { background: var(--accent-ink); border-color: var(--accent-ink); }
.btn-dark {
  background: var(--ink);
  color: #fff;
  border-color: var(--ink);
}
.btn-dark:hover { background: #000; }
.btn-ghost {
  background: transparent;
  color: var(--ink);
  border-color: var(--line-strong);
}
.btn-ghost:hover { background: var(--sand); border-color: var(--ink); }

.link-arrow {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  text-decoration: none;
  color: var(--ink);
  font-weight: 600;
  font-size: 0.95rem;
  border-bottom: 1px solid transparent;
  padding-bottom: 2px;
}
.link-arrow:hover { border-bottom-color: var(--ink); }

/* ---------- Section heads ---------- */
section { padding: clamp(48px, 7vw, 88px) var(--gutter); max-width: var(--maxw); margin: 0 auto; }
.section-head {
  display: flex;
  flex-wrap: wrap;
  align-items: end;
  justify-content: space-between;
  gap: 12px 24px;
  margin-bottom: 28px;
}
.section-head h2 { margin-bottom: 0; }
.section-sub { color: var(--muted); margin: 4px 0 0; font-size: 0.98rem; }
.eyebrow, .kicker {
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--accent-ink);
  margin: 0 0 14px;
}
.kicker { color: var(--muted); margin-bottom: 8px; }

/* ---------- Hero ---------- */
.hero {
  display: grid;
  grid-template-columns: 1.05fr 1fr;
  gap: clamp(24px, 5vw, 64px);
  align-items: center;
  padding-top: clamp(40px, 6vw, 72px);
}
.hero-text { max-width: 560px; }
.hero-lede {
  font-size: 1.1rem;
  color: var(--ink-2);
  max-width: 48ch;
  margin-bottom: 28px;
}
.hero-cta { display: flex; gap: 12px; flex-wrap: wrap; }

.hero-art {
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-template-rows: 180px 180px;
  gap: 14px;
  min-width: 0;
}
.hero-tile {
  border-radius: var(--radius);
  position: relative;
  overflow: hidden;
}
.tile-1 {
  background:
    radial-gradient(circle at 30% 30%, #e8d6c2 0%, #c9a989 60%, #a87d5b 100%);
  grid-row: span 2;
}
.tile-2 { background: linear-gradient(140deg, #d9d2c5, #b6b09e); }
.tile-3 { background: linear-gradient(140deg, var(--moss), #4f5b41); }
.tile-4 { background: linear-gradient(140deg, var(--sky), #8aa1a8); }

.hero-tile::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 70% 80%, rgba(255,255,255,0.18), transparent 50%),
    radial-gradient(circle at 20% 20%, rgba(255,255,255,0.12), transparent 40%);
}

@media (max-width: 820px) {
  .hero { grid-template-columns: 1fr; }
  .hero-art { grid-template-rows: 140px 140px; }
}

/* ---------- Categories ---------- */
.cat-grid {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
}
.cat-card {
  position: relative;
  display: block;
  aspect-ratio: 4 / 5;
  border-radius: var(--radius);
  overflow: hidden;
  text-decoration: none;
  color: #fff;
  font-family: var(--font-display);
  font-size: 1.4rem;
  transition: transform 0.2s ease;
}
.cat-card span {
  position: absolute;
  left: 16px;
  bottom: 14px;
  z-index: 2;
  text-shadow: 0 1px 6px rgba(0,0,0,0.4);
}
.cat-card::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,0.55) 0%, transparent 55%);
}
.cat-card:hover { transform: translateY(-2px); }

.cat-apparel { background: linear-gradient(160deg, #b9a48a, #6e5a44); }
.cat-home    { background: linear-gradient(160deg, #d8c8b6, #8a7560); }
.cat-kitchen { background: linear-gradient(160deg, #8a9b88, #4d5e4f); }
.cat-accents { background: linear-gradient(160deg, #c2a9a1, #76544d); }

@media (max-width: 720px) {
  .cat-grid { grid-template-columns: repeat(2, 1fr); }
}

/* ---------- Products ---------- */
.product-grid {
  list-style: none;
  padding: 0;
  margin: 0;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 22px 18px;
}
@media (max-width: 980px) { .product-grid { grid-template-columns: repeat(3, 1fr); } }
@media (max-width: 720px) { .product-grid { grid-template-columns: repeat(2, 1fr); } }

.product {
  background: transparent;
  display: flex;
  flex-direction: column;
  position: relative;
}
.product-media {
  position: relative;
  aspect-ratio: 4 / 5;
  border-radius: var(--radius);
  overflow: hidden;
  background: var(--sand);
}
.product-media::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 65% 75%, rgba(255,255,255,0.18), transparent 55%),
    radial-gradient(circle at 25% 25%, rgba(255,255,255,0.12), transparent 50%);
  pointer-events: none;
}
.product-tag {
  position: absolute;
  top: 10px;
  left: 10px;
  background: #fff;
  color: var(--ink);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  padding: 5px 9px;
  border-radius: 999px;
  z-index: 2;
}
.product-tag.sale { background: var(--accent); color: #fff; }
.add-btn {
  position: absolute;
  right: 10px;
  bottom: 10px;
  z-index: 2;
  appearance: none;
  background: #fff;
  color: var(--ink);
  border: 1px solid var(--line-strong);
  border-radius: 999px;
  font-weight: 600;
  font-size: 0.85rem;
  padding: 8px 14px;
  cursor: pointer;
  opacity: 0;
  transform: translateY(6px);
  transition: opacity 0.18s ease, transform 0.18s ease, background 0.15s ease,
    color 0.15s ease;
}
.product-media:hover .add-btn,
.add-btn:focus-visible {
  opacity: 1;
  transform: translateY(0);
}
.add-btn:hover { background: var(--ink); color: #fff; border-color: var(--ink); }

.product-info {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
  padding: 14px 2px 4px;
}
.product-name {
  font-family: var(--font-display);
  font-size: 1.05rem;
  font-weight: 500;
  color: var(--ink);
  text-decoration: none;
  line-height: 1.3;
}
.product-name:hover { text-decoration: underline; text-underline-offset: 3px; }
.product-cat { color: var(--muted); font-size: 0.85rem; margin: 2px 0 0; }
.product-price { font-weight: 600; color: var(--ink); white-space: nowrap; font-size: 0.98rem; }
.price-was { color: var(--muted); text-decoration: line-through; font-weight: 400; margin-right: 6px; font-size: 0.85rem; }
.price-now { color: var(--accent-ink); }

/* product palettes */
.p-1 { background: linear-gradient(160deg, #d9c7b3, #a07f63); }
.p-2 { background: linear-gradient(160deg, #cfd6c8, #6b7a5a); }
.p-3 { background: linear-gradient(160deg, #efe7da, #b4a285); }
.p-4 { background: linear-gradient(160deg, #c7d3d8, #6f8a92); }
.p-5 { background: linear-gradient(160deg, #e5d2c5, #b9826a); }
.p-6 { background: linear-gradient(160deg, #d6cfc3, #8a8071); }
.p-7 { background: linear-gradient(160deg, #c8b9a5, #7d6a52); }
.p-8 { background: linear-gradient(160deg, #b5b8b0, #5a5d55); }

/* ---------- Deals ---------- */
.deals {
  background: var(--ink);
  max-width: none;
  margin: 0;
  color: #f4f1ec;
}
.deals .section-head h2,
.deals .section-sub { color: #f4f1ec; }
.deals .section-sub { color: #c8c2b8; }
.deals > * { max-width: var(--maxw); margin-left: auto; margin-right: auto; }

.deals-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: 18px;
}
.deal {
  background: #232220;
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
}
.deal-feature { grid-row: span 1; }
.deal-art {
  aspect-ratio: 16 / 9;
  position: relative;
}
.deal-feature .deal-art { aspect-ratio: 16 / 8; }
.deal-art-1 { background: linear-gradient(135deg, #c9b496 0%, #8e6a48 100%); }
.deal-art-2 { background: linear-gradient(135deg, #6b7a5a 0%, #3e4734 100%); }
.deal-art-3 { background: linear-gradient(135deg, #5a4754 0%, #2f2530 100%); }
.deal-body { padding: 22px; display: flex; flex-direction: column; gap: 4px; }
.deal-body h3 { color: #fff; font-size: 1.4rem; }
.deal-feature .deal-body h3 { font-size: 1.7rem; }
.deal-body p { color: #c8c2b8; }
.deal-body .btn { align-self: flex-start; margin-top: 8px; background: #fff; color: var(--ink); border-color: #fff; }
.deal-body .btn:hover { background: var(--accent); color: #fff; border-color: var(--accent); }
.deal-body .link-arrow { color: #fff; align-self: flex-start; margin-top: 6px; }
.deal-body .link-arrow:hover { border-bottom-color: #fff; }

.badge {
  display: inline-block;
  background: rgba(255,255,255,0.1);
  color: #f4f1ec;
  border: 1px solid rgba(255,255,255,0.18);
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-bottom: 8px;
}
.badge-accent { background: var(--accent); color: #fff; border-color: var(--accent); }

@media (max-width: 900px) {
  .deals-grid { grid-template-columns: 1fr 1fr; }
  .deal-feature { grid-column: span 2; }
}
@media (max-width: 600px) {
  .deals-grid { grid-template-columns: 1fr; }
  .deal-feature { grid-column: span 1; }
}

/* ---------- Editorial ---------- */
.editorial-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  gap: 22px;
}
.story {
  display: flex;
  flex-direction: column;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.story:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }
.story-art { aspect-ratio: 16 / 10; position: relative; }
.story-lead .story-art { aspect-ratio: 16 / 12; }
.story-art-1 { background: linear-gradient(135deg, #d8c8b6, #7a604a); }
.story-art-2 { background: linear-gradient(135deg, #c7d3d8, #607880); }
.story-art-3 { background: linear-gradient(135deg, #c9b794, #6f5b3c); }
.story-body { padding: 20px 22px 22px; }
.story-body h3 { font-size: 1.25rem; margin-bottom: 8px; }
.story-lead .story-body h3 { font-size: 1.55rem; }
.story-body h3 a {
  color: var(--ink);
  text-decoration: none;
  background-image: linear-gradient(currentColor, currentColor);
  background-size: 0% 1px;
  background-repeat: no-repeat;
  background-position: 0 100%;
  transition: background-size 0.25s ease;
}
.story-body h3 a:hover { background-size: 100% 1px; }
.meta { color: var(--muted); font-size: 0.83rem; text-transform: uppercase; letter-spacing: 0.08em; margin: 8px 0 0; }

@media (max-width: 900px) {
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .story-lead { grid-column: span 2; }
}
@media (max-width: 600px) {
  .editorial-grid { grid-template-columns: 1fr; }
  .story-lead { grid-column: span 1; }
}

/* ---------- Newsletter ---------- */
.newsletter {
  background: var(--sand);
  max-width: none;
  margin: 0;
}
.newsletter-inner {
  max-width: var(--maxw);
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 1.1fr;
  gap: clamp(24px, 5vw, 56px);
  align-items: center;
}
.newsletter h2 { margin-bottom: 8px; }
.newsletter p { color: var(--ink-2); margin: 0; }

.news-form label {
  display: block;
  font-weight: 600;
  margin-bottom: 8px;
  font-size: 0.95rem;
}
.req { color: var(--accent-ink); margin-left: 2px; }
.news-row { display: flex; gap: 8px; flex-wrap: wrap; }
.news-row input {
  flex: 1 1 220px;
  min-width: 0;
  font: inherit;
  padding: 12px 14px;
  border-radius: 999px;
  border: 1px solid var(--line-strong);
  background: #fff;
  color: var(--ink);
}
.news-row input::placeholder { color: var(--muted); }
.news-row input:focus-visible { outline: 2px solid var(--ink); outline-offset: 2px; }
.news-row input[aria-invalid="true"] {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(181, 74, 43, 0.15);
}
.news-help { color: var(--muted); font-size: 0.85rem; margin: 10px 0 0; }
.news-status {
  margin: 8px 0 0;
  font-size: 0.9rem;
  font-weight: 600;
  min-height: 1.2em;
}
.news-status.error { color: var(--accent-ink); }
.news-status.success { color: #2f5a3a; }

@media (max-width: 720px) { .newsletter-inner { grid-template-columns: 1fr; } }

/* ---------- Footer ---------- */
.site-footer {
  background: var(--ink);
  color: #d6d1c9;
  padding: 56px var(--gutter) 24px;
}
.footer-inner {
  max-width: var(--maxw);
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 2fr;
  gap: 32px;
  padding-bottom: 36px;
  border-bottom: 1px solid #2c2a27;
}
.foot-brand .brand-name { color: #fff; font-size: 1.4rem; margin: 0 0 6px; font-family: var(--font-display); font-weight: 600; }
.foot-tag { margin: 0; color: #b3ada3; font-size: 0.95rem; max-width: 28ch; }
.foot-cols { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.foot-cols h2 {
  font-family: var(--font-sans);
  font-size: 0.78rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #fff;
  margin: 0 0 14px;
  font-weight: 700;
}
.foot-cols ul { list-style: none; padding: 0; margin: 0; display: grid; gap: 8px; }
.foot-cols a {
  color: #d6d1c9;
  text-decoration: none;
  font-size: 0.95rem;
}
.foot-cols a:hover { color: #fff; text-decoration: underline; text-underline-offset: 3px; }

.footer-base {
  max-width: var(--maxw);
  margin: 0 auto;
  padding-top: 20px;
  display: flex;
  flex-wrap: wrap;
  gap: 12px 24px;
  justify-content: space-between;
  font-size: 0.85rem;
  color: #a8a298;
}
.footer-base p { margin: 0; }
.legal { list-style: none; display: flex; gap: 18px; padding: 0; margin: 0; }
.legal a { color: #a8a298; text-decoration: none; }
.legal a:hover { color: #fff; }

@media (max-width: 720px) {
  .footer-inner { grid-template-columns: 1fr; }
  .foot-cols { grid-template-columns: repeat(2, 1fr); }
}

/* ---------- Toast ---------- */
.toast {
  position: fixed;
  left: 50%;
  bottom: 24px;
  transform: translateX(-50%) translateY(20px);
  background: var(--ink);
  color: #fff;
  padding: 12px 18px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 0.9rem;
  box-shadow: var(--shadow-md);
  z-index: 200;
  opacity: 0;
  transition: opacity 0.2s ease, transform 0.2s ease;
}
.toast.show {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}

/* ---------- Reduced motion ---------- */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    transition-duration: 0.001ms !important;
  }
}

/* ---------- Forced colors ---------- */
@media (forced-colors: active) {
  .btn, .icon-btn, .news-row input, .product-tag, .badge, .cat-card, .deal, .story {
    border: 1px solid ButtonBorder;
  }
  .btn-primary, .btn-dark { background: ButtonText; color: ButtonFace; }
  .cart-count { background: Highlight; color: HighlightText; }
  :focus-visible { outline: 2px solid CanvasText; }
}
